"""Procedural Arcade stage backdrop atlas (WP-sf-stage-backdrop; arena-art pass 2026-11-13). Original art generated by this script
(no legacy pixels used).
Run: ~/claudetmp/v/bin/python tools/assets/stage-gen/stagebg.py public/assets/img/stagebg.png   (numpy + Pillow; fixed seeds, so the
output is byte-identical)
Atlas 2400 x 3576, truecolour RGBA, layout shared with src/game/fx/terrain-stage-layout.ts (a test pins the numbers):
  - rows 0..1999: the FAR layer, one 2400 x 500 skyline per stage (fire, water, earth, air); its bottom edge is the arena wall.
    Only its lower part shows in play (the crowd covers the rest), so the light sits low, at the horizon.
  - rows 2000..3535: the CROWD strip, 3 frames per stage (2400 x 128 each, frame order stage-major): three tiers of the stage's
    folk on stone terraces behind a parapet with braziers; members cheer in a rolling wave, flames flicker and banners sway
    from frame to frame. It fills the band from just under the top HUD down to the wall.
  - rows 3536..3575: ambient DRIFTERS, 2 frames per stage (64 x 40 each, wings up and down), left to right in stage order.
Look (owner, 2026-11-13: the old crowd read as dead dark silhouettes and the band under the HUD as empty): a luminous mystic
palette, grim and painterly but lit. Skies glow at the horizon with a faint aurora and drifting motes; the crowd is lit from
below by the braziers and rimmed by the sky, the back tiers sink into a coloured haze, a few spectators hold up lit charms
and the banners carry the stage sigil faintly aglow. Everything is drawn at 2x and averaged down (soft edges), then lightly
desaturated with grain, like the painted floors (arena-floor.py) and Fiara's baked look.
"""
import random
import sys
import numpy as np
from PIL import Image, ImageDraw, ImageFilter

W = 2400
FAR_H = 500
CROWD_H = 128
CROWD_FRAMES = 3
FLY_W, FLY_H = 64, 40
CROWD_Y0 = 4 * FAR_H
FLY_Y0 = CROWD_Y0 + 4 * CROWD_FRAMES * CROWD_H
H = FLY_Y0 + FLY_H

# per stage: sky top, sky horizon, far silhouette, near silhouette, glow accent, rim light, drifter body
STAGES = [
    dict(top=(30, 12, 20), hor=(138, 62, 38), far=(70, 34, 32), near=(38, 20, 22), glow=(255, 140, 60), rim=(230, 140, 84), body=(40, 20, 22)),
    dict(top=(8, 20, 32), hor=(48, 100, 112), far=(30, 62, 74), near=(18, 36, 46), glow=(140, 226, 228), rim=(140, 210, 220), body=(16, 32, 42)),
    dict(top=(26, 26, 18), hor=(106, 98, 66), far=(72, 66, 46), near=(44, 40, 30), glow=(226, 204, 124), rim=(210, 190, 130), body=(40, 36, 26)),
    dict(top=(28, 28, 50), hor=(112, 108, 150), far=(78, 76, 108), near=(50, 50, 74), glow=(224, 218, 255), rim=(214, 210, 246), body=(50, 48, 72)),
]
GRAIN = (3, 3, 3, 2)  # film grain amplitude per stage


def fbm(rng, w, h, cell, octs=4, aniso=1.0):
    """Smooth value noise in 0..1 (bicubic-upsampled random grids, summed over octaves); cell = feature size in px."""
    t, amp, tot = np.zeros((h, w), np.float32), 1.0, 0.0
    for o in range(octs):
        c = max(2.0, cell / (2 ** o))
        gw, gh = int(w / (c * aniso)) + 3, int(h / c) + 3
        g = Image.fromarray((rng.random((gh, gw)) * 255).astype(np.uint8)).resize((int(gw * c * aniso), int(gh * c)), Image.BICUBIC)
        t += amp * np.asarray(g, np.float32)[:h, :w] / 255.0
        tot += amp
        amp *= 0.5
    return t / tot


def glow_blob(box, color, blur):
    """A soft glow: an ellipse drawn on a transparent layer and gaussian-blurred, composited by the caller."""
    layer = Image.new("RGBA", (W, FAR_H), color + (0,))
    ImageDraw.Draw(layer).ellipse(box, fill=color + (255,))
    return layer.filter(ImageFilter.GaussianBlur(blur))


def finish(im, s, k, rng):
    """The painterly pass over a far layer: soften edges, haze toward the horizon, mottle, vignette, desaturate, grain."""
    a = np.asarray(im.filter(ImageFilter.GaussianBlur(1.1)).convert("RGB"), np.float32)
    yy = np.linspace(0, 1, FAR_H, dtype=np.float32)[:, None, None]
    mott = fbm(rng, W, FAR_H, 90, 5, 2.0)[:, :, None]
    a = a * (0.88 + 0.24 * mott)  # broken-tone mottling
    haze = np.array(s["hor"], np.float32)[None, None, :]
    a = a * (1 - 0.22 * yy) + haze * 0.22 * yy  # distance haze lifts the lower sky
    xx = np.linspace(-1, 1, W, dtype=np.float32)[None, :, None]
    a = a * (1 - 0.18 * np.abs(xx) ** 2)  # a little darker toward the left and right edges
    luma = (a * np.array([0.3, 0.59, 0.11], np.float32)).sum(2, keepdims=True)
    a = luma + (a - luma) * 0.85  # pull the saturation down a touch
    streak = (fbm(rng, W, FAR_H, 7, 2, 4.0) - 0.5) * 2 * GRAIN[k] * 1.6  # brush-stroke streaks
    speck = rng.normal(0, GRAIN[k] * 0.8, (FAR_H, W)).astype(np.float32)
    return Image.fromarray(np.clip(a + (streak + speck)[:, :, None], 0, 255).astype(np.uint8))


def lerp(a, b, t):
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


def shade(c, k):
    return tuple(max(0, min(255, int(v * k))) for v in c)


def sky(s, rng):
    """A smooth top-to-horizon gradient with large soft tonal drifts (no bands); the light pools at the horizon."""
    t = np.linspace(0, 1, FAR_H - 40, dtype=np.float32)[:, None] ** 1.6
    n = fbm(np.random.default_rng(rng.randrange(1 << 30)), W, FAR_H - 40, 160, 4, 2.5)
    t = np.clip(t + (n - 0.5) * 0.3, 0, 1)[:, :, None]
    top, hor = np.array(s["top"], np.float32), np.array(s["hor"], np.float32)
    a = top + (hor - top) * t
    full = np.zeros((FAR_H, W, 3), np.float32)
    full[: FAR_H - 40] = a
    full[FAR_H - 40:] = a[-1]
    return Image.fromarray(full.astype(np.uint8))


def mountains(im, s, rng, base_y, amp, color, step, peak):
    d = ImageDraw.Draw(im)
    pts = [(0, FAR_H)]
    x = 0
    while x <= W + step:
        y = base_y - rng.randint(amp // 3, amp)
        pts += [(x, base_y), (x + step // 2, y)] if peak else [(x, y), (x + step // 2, y)]
        x += step
    pts.append((W, FAR_H))
    d.polygon(pts, fill=color)
    d.line(pts[1:-1], fill=lerp(color, s["rim"], 0.5), width=2)


def add_glow(im, box, color, blur, strength):
    """Composite a soft glow disc at `strength` (0..1) onto an RGB image."""
    g = glow_blob(box, color, blur)
    g.putalpha(g.getchannel("A").point(lambda v: int(v * strength)))
    return Image.alpha_composite(im.convert("RGBA"), g).convert("RGB")


def overcast(im, s, rng, lo, hi, strength):
    """Low cloud banks (no puffs): stretched noise thresholded softly, lit from the horizon, between rows lo..hi."""
    n = fbm(np.random.default_rng(rng.randrange(1 << 30)), W, FAR_H, 120, 5, 3.5)
    m = np.clip((n - 0.45) * 3.0, 0, 1)
    yy = np.arange(FAR_H, dtype=np.float32)
    band = np.clip(np.minimum((yy - lo) / 60.0, (hi - yy) / 60.0), 0, 1)[:, None]
    m = (m * band * strength)[:, :, None]
    base = np.asarray(im, np.float32)
    lit = np.clip(yy / FAR_H, 0, 1)[:, None, None]  # clouds near the horizon catch more light
    ash = np.array(s["hor"], np.float32) * (0.42 + 0.3 * lit) + np.array(s["glow"], np.float32) * 0.12 * lit
    return Image.fromarray(np.clip(base * (1 - m) + ash * m, 0, 255).astype(np.uint8))


def aurora(im, s, rng, lo, hi, strength):
    """Mystic light curtains: tall thin noise ribbons along a wavy band, added in the stage's glow colour."""
    r = np.random.default_rng(rng.randrange(1 << 30))
    curtain = fbm(r, W, FAR_H, 140, 3, 0.2)
    sway = (fbm(r, W, 1, 400, 2)[0] - 0.5) * 120
    yy = np.arange(FAR_H, dtype=np.float32)[:, None]
    mid = (lo + hi) / 2 + sway[None, :]
    band = np.exp(-0.5 * ((yy - mid) / ((hi - lo) / 4)) ** 2)
    m = np.clip((curtain - 0.5) * 2.0, 0, 1) * band * strength * 0.6
    m = m * np.clip((fbm(r, W, FAR_H, 300, 2) - 0.35) * 2.5, 0, 1)  # only in places
    base = np.asarray(im, np.float32)
    col = np.array(lerp(s["glow"], s["rim"], 0.5), np.float32)
    return Image.fromarray(np.clip(base + m[:, :, None] * col, 0, 255).astype(np.uint8))


def motes(im, s, rng, lo, hi, n):
    """Drifting embers / spray / spores / sky-dust: sparse soft points of light near the horizon."""
    layer = Image.new("L", (W, FAR_H))
    d = ImageDraw.Draw(layer)
    for _ in range(n):
        x, y, r = rng.uniform(0, W), rng.uniform(lo, hi), rng.uniform(0.8, 2.0)
        d.ellipse([x - r, y - r, x + r, y + r], fill=rng.randint(120, 255))
    m = np.asarray(layer.filter(ImageFilter.GaussianBlur(1.2)), np.float32)[:, :, None] / 255.0
    halo = np.asarray(layer.filter(ImageFilter.GaussianBlur(5)), np.float32)[:, :, None] / 255.0
    base = np.asarray(im, np.float32)
    col = np.array(s["glow"], np.float32)
    return Image.fromarray(np.clip(base + (m * 0.9 + halo * 1.6) * col, 0, 255).astype(np.uint8))


def far_layer(i, s, rng):
    im = sky(s, rng)
    if i == 0:  # fire: a molten glow low behind volcanic ridges with lava seams, embers rising
        im = add_glow(im, [W // 2 - 700, FAR_H - 200, W // 2 + 700, FAR_H + 140], s["glow"], 110, 0.42)
        im = overcast(im, s, rng, 60, 360, 0.5)
        im = aurora(im, s, rng, 250, 450, 0.35)
    elif i == 1:  # water: a pale moon low behind drifting cloud, a cold aurora over a far shoreline
        im = add_glow(im, [W // 2 + 240, 300, W // 2 + 380, 440], s["glow"], 40, 0.7)
        im = add_glow(im, [W // 2 - 800, FAR_H - 180, W // 2 + 800, FAR_H + 120], s["glow"], 120, 0.22)
        im = overcast(im, s, rng, 40, 340, 0.55)
        im = aurora(im, s, rng, 240, 440, 0.55)
    elif i == 2:  # earth: a hazy low sun in a golden dust-laden sky
        im = add_glow(im, [W // 2 - 520, FAR_H - 220, W // 2 + 520, FAR_H + 100], s["glow"], 100, 0.38)
        im = overcast(im, s, rng, 40, 360, 0.4)
        im = aurora(im, s, rng, 260, 450, 0.25)
    else:  # air: a bright layered overcast with a pale sun breaking through
        im = add_glow(im, [W // 2 - 600, FAR_H - 240, W // 2 + 600, FAR_H + 80], s["glow"], 110, 0.32)
        im = overcast(im, s, rng, 0, 400, 0.75)
        im = aurora(im, s, rng, 240, 440, 0.4)
    d = ImageDraw.Draw(im)
    if i == 0:
        craters = []
        for cx in (300, 900, 1500, 2100):
            h = rng.randint(110, 170)
            top, base = FAR_H - 40 - h, FAR_H - 40
            left = [(cx - 240 + int(200 * t), base - int(h * t) + rng.randint(-6, 6)) for t in np.linspace(0, 1, 12)]
            right = [(cx + 40 + int(200 * t), top + int(h * t) + rng.randint(-6, 6)) for t in np.linspace(0, 1, 12)]
            d.polygon(left + [(cx - 40, top), (cx - 14, top + 8), (cx + 14, top + 6)] + right, fill=s["far"])  # a notched crater
            for k in range(3):  # lava seams: jagged, thinning down the flank
                x, y = cx + rng.randint(-24, 24), top + 6
                pts = [(x, y)]
                while y < base - 24:
                    y += rng.randint(10, 22)
                    x += rng.randint(-14, 14)
                    pts.append((x, y))
                d.line(pts, fill=lerp(s["far"], s["glow"], 0.5), width=2)
            craters.append((cx, top))
        for cx, top in craters:
            im = add_glow(im, [cx - 40, top - 26, cx + 40, top + 12], s["glow"], 18, 0.5)
        d = ImageDraw.Draw(im)
    elif i == 1:
        mountains(im, s, rng, FAR_H - 90, 70, s["far"], 160, True)
        for x in (500, 1300, 1900):  # distant hulls
            d.polygon([(x, FAR_H - 110), (x, FAR_H - 60), (x - 30, FAR_H - 60)], fill=s["near"])
            d.polygon([(x - 36, FAR_H - 56), (x + 36, FAR_H - 56), (x + 24, FAR_H - 46), (x - 24, FAR_H - 46)], fill=s["near"])
        lx = 1000  # a lighthouse with a faint cold lamp
        d.rectangle([lx, FAR_H - 200, lx + 24, FAR_H - 60], fill=s["near"])
        d.polygon([(lx - 6, FAR_H - 200), (lx + 30, FAR_H - 200), (lx + 12, FAR_H - 230)], fill=s["near"])
        im = add_glow(im, [lx - 10, FAR_H - 214, lx + 34, FAR_H - 190], s["glow"], 8, 0.8)
        d = ImageDraw.Draw(im)
    elif i == 2:
        for cx in range(140, W, 330):
            w, h = rng.randint(120, 220), rng.randint(60, 150)
            x0, x1, top = cx - w // 2, cx + w // 2, FAR_H - 40 - h
            crest = [(x0, top + rng.randint(0, 30))]  # a broken, stepped top: a ruin, not a box
            for x in range(x0 + 16, x1, 16):
                crest.append((x, top + rng.choice((0, 0, 8, 18, 34))))
            crest.append((x1, top + rng.randint(10, 50)))
            d.polygon([(x0, FAR_H - 40)] + crest + [(x1, FAR_H - 40)], fill=s["far"])
            d.line(crest, fill=lerp(s["far"], s["rim"], 0.6), width=2)
            for k in range(3):
                y = top + 40 + k * 18
                if y < FAR_H - 44:
                    d.line([(x0 + 4, y), (x1 - 4, y)], fill=shade(s["far"], 0.8), width=2)
            for k in range(rng.randint(1, 3)):  # dark window slits
                wx = rng.randint(x0 + 14, x1 - 20)
                d.rectangle([wx, top + 50, wx + 6, top + 72], fill=shade(s["far"], 0.6))
    else:  # air: floating slabs with ruined pillars, lit from above
        for cx in (400, 1200, 2000):
            y = FAR_H - 170 + rng.randint(-30, 30)
            d.polygon([(cx - 90, y), (cx + 90, y), (cx + 40, y + 60), (cx, y + 90), (cx - 40, y + 60)], fill=s["far"])
            d.line([(cx - 90, y), (cx + 90, y)], fill=s["rim"], width=2)
            for k in (-2, -1, 1, 2):
                top = y - rng.randint(14, 46)
                d.rectangle([cx + k * 26 - 4, top, cx + k * 26 + 4, y], fill=s["far"])
    im = motes(im, s, rng, 280, FAR_H - 50, 160)
    # the arena wall: a band along the bottom edge (the crowd's parapet covers it)
    d = ImageDraw.Draw(im)
    d.rectangle([0, FAR_H - 40, W, FAR_H], fill=s["near"])
    d.line([(0, FAR_H - 40), (W, FAR_H - 40)], fill=s["rim"], width=1)
    for x in range(0, W, 48):
        d.line([(x, FAR_H - 38), (x, FAR_H)], fill=shade(s["near"], 0.7), width=2)
    return finish(im, s, i, np.random.default_rng(900 + i))


CROWD = [  # per stage: cloth swatches, skin, light (braziers, held charms), rim (sky light on top edges), haze, stone, banner
    dict(cloth=[(84, 42, 36), (104, 60, 42), (66, 40, 46), (92, 70, 58)], skin=(120, 78, 58), light=(255, 136, 52), rim=(255, 170, 110),
         haze=(96, 44, 34), stone=(66, 46, 44), banner=(120, 34, 26)),
    dict(cloth=[(36, 62, 76), (50, 80, 86), (60, 70, 92), (32, 54, 64)], skin=(88, 116, 122), light=(110, 224, 230), rim=(150, 226, 236),
         haze=(36, 78, 92), stone=(40, 58, 68), banner=(24, 74, 94)),
    dict(cloth=[(76, 68, 44), (62, 76, 42), (88, 70, 48), (56, 60, 40)], skin=(116, 100, 72), light=(220, 226, 120), rim=(232, 214, 150),
         haze=(78, 78, 50), stone=(70, 64, 52), banner=(58, 82, 34)),
    dict(cloth=[(80, 78, 104), (96, 92, 118), (70, 72, 96), (108, 102, 128)], skin=(132, 126, 152), light=(206, 196, 255), rim=(228, 224, 255),
         haze=(80, 78, 112), stone=(76, 74, 96), banner=(80, 68, 130)),
]
SS = 2  # the crowd and drifters are drawn at twice the size and averaged down (soft painted edges, no aliasing)
# Tiers back to front: (feet y, body height, spacing, light share), in strip px; the front parapet starts at RAIL_Y.
TIERS = ((54, 17, 26, 0.6), (86, 22, 32, 0.8), (118, 27, 40, 1.0))
RAIL_Y = 112
BRAZIERS = range(150, W, 300)
BANNERS = range(300, W, 600)


def person(d, ld, i, c, x, base, h, up, cloth, holds, eyes):
    """One spectator (supersampled px) standing at `base`: robed body, hooded head with the stage's mark, two arms. A holder
    carries a lit charm (raised when cheering), a few show glowing eyes: both go to `ld`, the light mask."""
    bw, r = h * 0.34, h * 0.21
    hy = base - h - r * 0.8
    d.polygon([(x - bw, base), (x - bw * 0.7, base - h * 0.95), (x, base - h * 1.02), (x + bw * 0.7, base - h * 0.95), (x + bw, base)], fill=cloth)
    if i == 2:  # earth folk: blocky heads
        d.rectangle([x - r, hy - r, x + r, hy + r], fill=c["skin"])
    else:
        d.ellipse([x - r, hy - r, x + r, hy + r], fill=c["skin"])
    d.pieslice([x - r * 1.15, hy - r * 1.2, x + r * 1.15, hy + r * 1.1], 180, 360, fill=cloth)  # hood
    if i == 0 and int(x) % 5 > 1:  # fire: horns on most of them
        for sgn in (-1, 1):
            d.polygon([(x + sgn * r * 0.7, hy - r * 0.6), (x + sgn * (r + 4 * SS), hy - r - 8 * SS), (x + sgn * r * 0.15, hy - r)], fill=cloth)
    elif i == 1:  # water: a fin crest
        d.polygon([(x - 3 * SS, hy - r), (x, hy - r - 9 * SS), (x + 3 * SS, hy - r)], fill=cloth)
    elif i == 3:  # air: wing tufts
        for sgn in (-1, 1):
            d.polygon([(x + sgn * r, hy), (x + sgn * (r + 8 * SS), hy - 6 * SS), (x + sgn * (r + 2 * SS), hy + 4 * SS)], fill=cloth)
    sy, aw = base - h * 0.85, max(2, int(h * 0.16))
    for sgn in (-1, 1):
        hand = (x + sgn * (bw + h * 0.25), sy - h * 0.62) if up else (x + sgn * (bw + h * 0.1), sy + h * 0.45)
        d.line([(x + sgn * bw * 0.7, sy), hand], fill=cloth, width=aw)
        if holds and sgn == 1 and ld is not None:
            ld.ellipse([hand[0] - 3 * SS, hand[1] - 3 * SS, hand[0] + 3 * SS, hand[1] + 3 * SS], fill=255)
    if eyes and ld is not None:
        for sgn in (-1, 1):
            ex = x + sgn * r * 0.38
            ld.ellipse([ex - SS, hy + r * 0.1 - SS * 0.6, ex + SS, hy + r * 0.1 + SS * 0.6], fill=200)


def premul_down(rgba):
    """Average a supersampled float RGBA (0..1) down by SS with premultiplied alpha (no dark fringes)."""
    h, w = rgba.shape[0] // SS, rgba.shape[1] // SS
    pool = lambda a: a.reshape(h, SS, w, SS, -1).mean((1, 3))  # noqa: E731
    al = pool(rgba[..., 3:])
    rgb = pool(rgba[..., :3] * rgba[..., 3:]) / np.maximum(al, 1e-6)
    return np.concatenate([rgb, al], -1)


def soft(a, r):
    return np.asarray(Image.fromarray((np.clip(a, 0, 1) * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(r)), np.float32) / 255.0


def over(out, rgb, m):
    """Paint opaque colour `rgb` with coverage `m` over a straight-alpha float RGBA (source-over)."""
    al = out[..., 3]
    new_al = m + al * (1 - m)
    mix = (rgb * m[..., None] + out[..., :3] * (al * (1 - m))[..., None]) / np.maximum(new_al, 1e-6)[..., None]
    return np.concatenate([mix, new_al[..., None]], -1)


def add_light(out, rgb_add, a_add):
    """Add light (premultiplied colour `rgb_add`, coverage `a_add`) onto a straight-alpha float RGBA."""
    al = out[..., 3]
    new_al = np.clip(al + a_add * (1 - al), 0, 1)
    rgb = (out[..., :3] * al[..., None] + rgb_add) / np.maximum(new_al, 1e-6)[..., None]
    return np.concatenate([np.clip(rgb, 0, 1), new_al[..., None]], -1)


def crowd_frames(i, seed):
    """CROWD_FRAMES 2400 x CROWD_H strips: three tiers of the stage's folk on stone terraces, lit from below by braziers on
    the parapet and rimmed by the sky, banners on poles between the sections; the back tiers sink into a luminous haze.
    Every member has a fixed phase, so cycling the frames rolls a cheer along the rows; flames and banners move with it."""
    c = CROWD[i]
    rng = random.Random(seed)
    nrng = np.random.default_rng(seed)
    w, h = W * SS, CROWD_H * SS
    people = []
    for t, (feet, size, step, _) in enumerate(TIERS):
        x = rng.randint(0, step)
        while x < W:
            people.append((t, x + rng.randint(-5, 5), feet, size + rng.randint(-3, 3), rng.choice(c["cloth"]),
                           rng.random() < 0.12, rng.random() < 0.18, rng.randrange(CROWD_FRAMES)))
            x += step + rng.randint(-5, 7)
    mott = fbm(nrng, w, h, 40, 3, 2.0)
    yy = np.arange(h, dtype=np.float32)[:, None] / SS
    xx = np.arange(w, dtype=np.float32)[None, :] / SS
    frames = []
    for k in range(CROWD_FRAMES):
        flick = [0.8 + 0.2 * ((bx // 150 * 7 + k * 5) % 11) / 10 for bx in BRAZIERS]
        pool = np.zeros((1, w), np.float32)
        for bx, f in zip(BRAZIERS, flick):
            pool = pool + f * np.exp(-0.5 * ((xx - bx) / 64.0) ** 2)
        out = np.zeros((h, w, 4), np.float32)
        glow_mask = np.zeros((h, w), np.float32)
        for t, (feet, size, step, share) in enumerate(TIERS):
            col = Image.new("RGB", (w, h))
            mask = Image.new("L", (w, h))
            lmask = Image.new("L", (w, h))
            d, md, ld = ImageDraw.Draw(col), ImageDraw.Draw(mask), ImageDraw.Draw(lmask)
            if t < 2:  # the terrace this tier stands on: a stone step whose lip catches the light
                d.rectangle([0, (feet - 2) * SS, w, h], fill=c["stone"])
                md.rectangle([0, (feet - 2) * SS, w, h], fill=255)
                for x in range(t * 37, W, 90):
                    d.line([(x * SS, (feet + 3) * SS), (x * SS, h)], fill=shade(c["stone"], 0.75), width=SS)
            for tt, x, ft, size_, cloth, holds, eyes, phase in people:
                if tt != t:
                    continue
                up = (phase + k) % CROWD_FRAMES == 0
                person(d, ld, i, c, x * SS, ft * SS, size_ * SS, up, cloth, holds, eyes)
                person(md, None, i, dict(c, skin=255), x * SS, ft * SS, size_ * SS, up, 255, False, False)
            if t == 1:  # banners on poles between the sections, swaying with the frame
                for bx in BANNERS:
                    sway = (k - 1) * 3
                    px = bx * SS
                    for dd, f in ((d, shade(c["stone"], 0.7)), (md, 255)):
                        dd.line([(px, 2 * SS), (px, (feet + 2) * SS)], fill=f, width=2 * SS)
                    poly = [(px + SS, 6 * SS), (px + 26 * SS, 6 * SS), (px + (26 + sway) * SS, 54 * SS), (px + (13 + sway) * SS, 46 * SS), (px + (1 + sway // 2) * SS, 54 * SS)]
                    d.polygon(poly, fill=c["banner"])
                    md.polygon(poly, fill=255)
                    sx, sy2 = px + (13 + sway // 2) * SS, 24 * SS
                    ld.ellipse([sx - 6 * SS, sy2 - 6 * SS, sx + 6 * SS, sy2 + 6 * SS], outline=150, width=SS)  # the stage sigil, faintly lit
                    ld.line([(sx, sy2 - 9 * SS), (sx, sy2 + 9 * SS)], fill=150, width=SS)
            m = np.asarray(mask, np.float32) / 255.0
            a = np.asarray(col, np.float32)
            top = np.clip(m - np.roll(m, 3 * SS, 0), 0, 1)  # top edges catch the sky
            under = np.clip(1 - (feet - yy) / (size * 1.8), 0, 1)  # brazier light climbs from the parapet
            lit = (0.62 + 0.4 * (mott - 0.5)) * (0.75 + 0.25 * share) + 0.9 * pool * under * share
            a = a * lit[..., None] + top[..., None] * np.asarray(c["rim"], np.float32) * 0.35 * share
            a = a + (pool * under * share * 0.22)[..., None] * np.asarray(c["light"], np.float32)
            hz = (1 - share) * 0.5  # the back tiers fade into the stage's haze
            a = a * (1 - hz) + np.asarray(c["haze"], np.float32) * hz
            out = over(out, np.clip(a / 255.0, 0, 1), m)
            glow_mask = glow_mask * (1 - m) + np.asarray(lmask, np.float32) / 255.0
        # the front parapet: carved stone with a lit lip, braziers along it
        rail = Image.new("RGB", (w, h))
        rm = Image.new("L", (w, h))
        flames = Image.new("L", (w, h))
        d, md, fd = ImageDraw.Draw(rail), ImageDraw.Draw(rm), ImageDraw.Draw(flames)
        d.rectangle([0, RAIL_Y * SS, w, h], fill=c["stone"])
        md.rectangle([0, RAIL_Y * SS, w, h], fill=255)
        for x in range(0, W, 24):
            d.line([(x * SS, (RAIL_Y + 5) * SS), (x * SS, h)], fill=shade(c["stone"], 0.72), width=SS)
        for j, (bx, f) in enumerate(zip(BRAZIERS, flick)):
            X = bx * SS
            bowl = [(X - 12 * SS, (RAIL_Y - 7) * SS), (X + 12 * SS, (RAIL_Y - 7) * SS), (X + 7 * SS, RAIL_Y * SS), (X - 7 * SS, RAIL_Y * SS)]
            d.polygon(bowl, fill=shade(c["stone"], 0.6))
            md.polygon(bowl, fill=255)
            base_y = (RAIL_Y - 7) * SS
            for tg, (dx, hh, wd) in enumerate(((0, 1.0, 5), (-5, 0.62, 4), (5, 0.7, 4), (-2, 0.4, 7))):  # licking tongues, not a cone
                fh = (15 + 8 * f + 3 * ((k + j + tg) % 3)) * SS * hh
                lean = ((k * 2 + j + tg) % 5 - 2) * SS
                x0 = X + dx * SS
                fd.polygon([(x0 - wd * SS, base_y), (x0 - wd * SS * 0.5 + lean // 2, base_y - fh * 0.5), (x0 + lean, base_y - fh),
                            (x0 + wd * SS * 0.5 + lean // 2, base_y - fh * 0.45), (x0 + wd * SS, base_y)], fill=170 if tg else 255)
        ra = np.asarray(rail, np.float32)
        rmk = np.asarray(rm, np.float32) / 255.0
        lip = np.clip(rmk - np.roll(rmk, 2 * SS, 0), 0, 1)
        ra = ra * (0.72 + 0.3 * (mott - 0.5) + 0.6 * pool)[..., None] + lip[..., None] * np.asarray(c["light"], np.float32) * (0.3 + 0.5 * pool)[..., None]
        out = over(out, np.clip(ra / 255.0, 0, 1), rmk)
        glow_mask = glow_mask * (1 - rmk)
        # light: flames, held charms, eyes and sigils glow on their own, with soft halos
        fl = soft(np.asarray(flames, np.float32) / 255.0, 1.2 * SS)
        inner = soft(np.asarray(flames.filter(ImageFilter.MinFilter(4 * SS + 1)), np.float32) / 255.0, 2 * SS)  # the hot heart
        charm = soft(glow_mask, 0.8 * SS)
        halo = np.clip(soft(fl, 14 * SS) * 1.2 + soft(glow_mask, 5 * SS) * 1.2, 0, 1)
        L = np.asarray(c["light"], np.float32) / 255.0
        deep = L * 0.85  # the flame is painted (not added): deep, smoky edges, a brighter heart, never white
        hot = np.minimum(L + 0.22, 1.0)
        flick_n = np.clip(fbm(nrng, w, h, 6, 2, 1.0) * 1.3 - 0.15, 0, 1)  # broken, smoky edges
        fcov = np.clip(fl * (0.55 + 0.45 * flick_n) * 1.25, 0, 1)
        out = over(out, deep[None, None, :] * (1 - inner[..., None]) + hot[None, None, :] * inner[..., None], fcov)
        rgb_add = halo[..., None] * L * 0.4 + charm[..., None] * hot * 0.8
        out = add_light(out, rgb_add, np.clip(halo * 0.3 + charm, 0, 1))
        small = premul_down(out)
        luma = (small[..., :3] * np.array([0.3, 0.59, 0.11], np.float32)).sum(2, keepdims=True)
        small[..., :3] = luma + (small[..., :3] - luma) * 0.88
        grain = (nrng.random(small.shape[:2]) - 0.5)[..., None] * 0.03
        small[..., :3] = np.clip(small[..., :3] + grain, 0, 1)
        frames.append(Image.fromarray((small * 255).round().astype(np.uint8)))
    return frames


def flyer(i, s, wings_up):
    """One 64 x 40 drifter: bat (fire), gull (water), hawk (earth), kite-bird (air), wings up or down; a dark body with a rim of
    sky light along its top edges and a lit eye."""
    m = Image.new("L", (FLY_W * SS, FLY_H * SS))
    d = ImageDraw.Draw(m)
    P = lambda pts: [(x * SS, y * SS) for x, y in pts]  # noqa: E731
    E = lambda b: [v * SS for v in b]  # noqa: E731
    cx, cy = FLY_W // 2, FLY_H // 2
    tip = -14 if wings_up else 12
    if i == 0:  # bat: scalloped wings
        d.polygon(P([(cx, cy), (cx - 28, cy + tip), (cx - 22, cy + tip + 10), (cx - 14, cy + tip + 4), (cx - 8, cy + 8)]), fill=255)
        d.polygon(P([(cx, cy), (cx + 28, cy + tip), (cx + 22, cy + tip + 10), (cx + 14, cy + tip + 4), (cx + 8, cy + 8)]), fill=255)
        d.ellipse(E([cx - 5, cy - 6, cx + 5, cy + 8]), fill=255)
    elif i == 1:  # gull: long thin curved wings
        d.line(P([(cx - 30, cy + tip), (cx - 12, cy - 2), (cx, cy + 2), (cx + 12, cy - 2), (cx + 30, cy + tip)]), fill=255, width=4 * SS, joint="curve")
        d.ellipse(E([cx - 4, cy - 3, cx + 5, cy + 5]), fill=255)
    elif i == 2:  # hawk: broad wings, fanned tail
        d.polygon(P([(cx - 6, cy), (cx - 28, cy + tip), (cx - 20, cy + tip + 12), (cx - 4, cy + 10)]), fill=255)
        d.polygon(P([(cx + 6, cy), (cx + 28, cy + tip), (cx + 20, cy + tip + 12), (cx + 4, cy + 10)]), fill=255)
        d.polygon(P([(cx - 6, cy + 8), (cx + 6, cy + 8), (cx + 10, cy + 18), (cx - 10, cy + 18)]), fill=255)
        d.ellipse(E([cx - 5, cy - 6, cx + 5, cy + 8]), fill=255)
    else:  # air: a kite-bird, diamond wings and a long tail
        d.polygon(P([(cx, cy - 2), (cx - 26, cy + tip), (cx - 8, cy + 6)]), fill=255)
        d.polygon(P([(cx, cy - 2), (cx + 26, cy + tip), (cx + 8, cy + 6)]), fill=255)
        d.line(P([(cx, cy + 4), (cx + 4, cy + 18), (cx - 3, cy + 26)]), fill=255, width=2 * SS)
        d.ellipse(E([cx - 4, cy - 5, cx + 4, cy + 7]), fill=255)
    a = np.asarray(m, np.float32) / 255.0
    top = np.clip(a - np.roll(a, 2 * SS, 0), 0, 1)
    rgb = np.ones(a.shape + (3,), np.float32) * np.asarray(s["body"], np.float32) / 255.0
    rgb = rgb + top[..., None] * np.asarray(s["rim"], np.float32) / 255.0 * 0.7
    out = np.concatenate([np.clip(rgb, 0, 1), a[..., None]], -1)
    eye = np.zeros(a.shape, np.float32)
    ey, ex = (cy - 2) * SS, (cx - 2) * SS
    eye[ey:ey + SS, ex:ex + SS] = 1
    eye = soft(eye, SS)
    eye = np.clip(eye / max(eye.max(), 1e-6), 0, 1)
    out = add_light(out, eye[..., None] * np.asarray(s["glow"], np.float32) / 255.0, eye)
    return Image.fromarray((premul_down(out) * 255).round().astype(np.uint8))


def main(out):
    rng = random.Random(20261112)
    sheet = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    for i, s in enumerate(STAGES):
        sheet.paste(far_layer(i, s, rng).convert("RGBA"), (0, i * FAR_H))
        for k, fr in enumerate(crowd_frames(i, 77 + i)):
            sheet.paste(fr, (0, CROWD_Y0 + (i * CROWD_FRAMES + k) * CROWD_H))
        for f in range(2):
            sheet.paste(flyer(i, s, f == 0), ((i * 2 + f) * FLY_W, FLY_Y0))
    sheet.save(out, optimize=True)  # truecolour: the soft light and haze would band in a small palette


main(sys.argv[1])
